import os, shutil, subprocess, tempfile, pprint
PACKIGNORE = "/work/repo/tools/packignore"
def mk(files):
    d = tempfile.mkdtemp(prefix="pack_")
    for rel, content in files.items():
        full = os.path.join(d, rel)
        os.makedirs(os.path.dirname(full) or d, exist_ok=True)
        with open(full, "w") as f:
            f.write(content or "")
    return d

def run_ignore(d):
    out = subprocess.run([PACKIGNORE, d], capture_output=True, text=True)
    if out.stderr: print("STDERR:", out.stderr)
    return sorted(out.stdout.splitlines())

def all_files(d):
    out = []
    for dp, dns, fns in os.walk(d):
        if os.path.samefile(dp, d) and ".git" in dns:
            dns.remove(".git")
        for fn in fns:
            rel = os.path.relpath(os.path.join(dp, fn), d).replace(os.sep, "/")
            out.append(rel)
    return sorted(out)

# Basic *.log test
d = mk({
    ".packignore": "*.log\n",
    "a.log": "", "a.LOG": "", "a.txt": "",
    "b/a.log": "", "b/a.txt": "",
    "b/c/a.log": "",
    "deep/one/two/three/f.log": "",
    "keep.log": "", "k.tmp": "",
})
print("ALL FILES:")
pprint.pp(all_files(d))
print("IGNORED:")
pprint.pp(run_ignore(d))
shutil.rmtree(d)
