"""Decide which files in a project tree are excluded by its .packignore files."""

import os
import re


def ignored_files(root):
    """Return the files under `root` that its .packignore files exclude.

    Paths are relative to `root`, use "/" as the separator, and are sorted.
    Only files are listed, never directories. A `.git` directory directly
    under `root` is skipped.
    """
    excluded = set()
    _walk(root, "", [], excluded, True)
    return sorted(excluded)


def _walk(root, rel_dir, scopes, excluded, is_root):
    full_dir = os.path.join(root, rel_dir) if rel_dir else root
    pack = os.path.join(full_dir, ".packignore")
    patterns = []
    if os.path.isfile(pack):
        with open(pack, "r", newline="") as f:
            text = f.read()
        for line in text.splitlines():
            p = _parse(line)
            if p is not None:
                patterns.append(p)
    new_scopes = scopes + [(rel_dir, patterns)]

    try:
        entries = os.listdir(full_dir)
    except OSError:
        return

    for name in entries:
        if is_root and name == ".git":
            continue
        full_entry = os.path.join(full_dir, name)
        rel = (rel_dir + "/" + name) if rel_dir else name
        is_dir = os.path.isdir(full_entry) and not os.path.islink(full_entry)
        if is_dir:
            if _is_excluded(rel, True, new_scopes):
                _walk_sealed(root, rel, new_scopes, excluded)
            else:
                _walk(root, rel, new_scopes, excluded, False)
        else:
            if _is_excluded(rel, False, new_scopes):
                excluded.add(rel)


def _walk_sealed(root, rel_dir, scopes, excluded):
    """Walk a subtree without loading further .packignore files."""
    full_dir = os.path.join(root, rel_dir)
    try:
        entries = os.listdir(full_dir)
    except OSError:
        return
    for name in entries:
        full_entry = os.path.join(full_dir, name)
        rel = rel_dir + "/" + name
        is_dir = os.path.isdir(full_entry) and not os.path.islink(full_entry)
        if is_dir:
            _walk_sealed(root, rel, scopes, excluded)
        else:
            if _is_excluded(rel, False, scopes):
                excluded.add(rel)


def _is_excluded(rel, is_dir, scopes):
    all_segs = rel.split("/")
    n = len(all_segs)
    for depth in range(n):
        path_segs = all_segs[: n - depth]
        entry_is_dir = is_dir if depth == 0 else True
        decision = None
        for scope_rel, patterns in scopes:
            scope_segs = scope_rel.split("/") if scope_rel else []
            if len(path_segs) <= len(scope_segs):
                continue
            if path_segs[: len(scope_segs)] != scope_segs:
                continue
            scoped = path_segs[len(scope_segs):]
            last_literal_negate = None
            last_glob_negate = None
            for p in patterns:
                if _pattern_matches(p, scoped, entry_is_dir):
                    if p["literal"]:
                        last_literal_negate = p["negate"]
                    else:
                        last_glob_negate = p["negate"]
            if last_literal_negate is not None:
                scope_dec = not last_literal_negate
            elif last_glob_negate is not None:
                scope_dec = not last_glob_negate
            else:
                continue
            decision = scope_dec
        if decision is not None:
            return decision
    return False


def _parse(line):
    line = line.strip()
    if not line or line.startswith(";"):
        return None
    negate = False
    if line.startswith("!"):
        negate = True
        line = line[1:]
    if not line:
        return None
    dir_only = False
    if line.endswith("/"):
        dir_only = True
        line = line[:-1]
    if not line:
        return None
    anchored = line.startswith("/") or "/" in line.rstrip("/")
    if line.startswith("/"):
        line = line[1:]
    if not line:
        return None
    if "/" in line:
        anchored = True
    literal = "*" not in line and "?" not in line
    segs = line.split("/")
    return {
        "negate": negate,
        "dir_only": dir_only,
        "anchored": anchored,
        "literal": literal,
        "segs": segs,
    }


def _pattern_matches(p, path_segs, is_dir):
    if p["dir_only"] and not is_dir:
        return False
    if p["anchored"]:
        return _match_full(p["segs"], path_segs)
    if not path_segs:
        return False
    return _seg_match(p["segs"][0], path_segs[-1])


def _match_full(pat_segs, path_segs):
    if not pat_segs:
        return not path_segs
    head = pat_segs[0]
    if head == "**":
        for i in range(len(path_segs) + 1):
            if _match_full(pat_segs[1:], path_segs[i:]):
                return True
        return False
    if not path_segs:
        return False
    if _seg_match(head, path_segs[0]):
        return _match_full(pat_segs[1:], path_segs[1:])
    return False


_SEG_CACHE = {}


def _seg_match(pat, seg):
    rx = _SEG_CACHE.get(pat)
    if rx is None:
        parts = []
        i = 0
        while i < len(pat):
            c = pat[i]
            if c == "*":
                while i + 1 < len(pat) and pat[i + 1] == "*":
                    i += 1
                parts.append("[^/]*")
            elif c == "?":
                parts.append("[^/]")
            else:
                parts.append(re.escape(c))
            i += 1
        rx = re.compile("".join(parts) + r"\Z")
        _SEG_CACHE[pat] = rx
    return rx.match(seg) is not None

