#!/usr/bin/env python3
"""Fuzz test: compare my implementation against packignore across many random trees."""
import os, random, shutil, subprocess, sys, tempfile
sys.path.insert(0, "/work/repo")

PACKIGNORE = "/work/repo/tools/packignore"

from snapshot.ignore import ignored_files as mine

def run_pkg(root):
    out = subprocess.run([PACKIGNORE, root], capture_output=True, text=True, check=True)
    return sorted(line for line in out.stdout.splitlines() if line)

NAMES = ["a", "b", "c", "x", "y", "sub", "deep", "foo", "bar", "keep", "src", "build", "a.log", "b.log", "keep.log", "x.txt", "y.txt", "a.b", "a.c"]
GLOB_SEGS = ["*", "a", "*.log", "*.b", "sub", "deep", "a*", "?.b", "**", "x", "y"]
LITERAL_SEGS = ["a", "b", "sub", "deep", "foo", "bar", "keep", "a.log", "a.b", "x.txt"]

def rand_file_tree(rng, depth=0, max_depth=3, max_entries=5):
    """Returns dict of {relpath: content_or_None}."""
    tree = {}
    n = rng.randint(1, max_entries)
    for _ in range(n):
        kind = rng.choice(["file", "file", "file", "dir"])
        name = rng.choice(NAMES)
        if kind == "file":
            tree[name] = None
        elif depth < max_depth:
            sub = rand_file_tree(rng, depth+1, max_depth, max_entries)
            for k, v in sub.items():
                tree[name + "/" + k] = v
    return tree

def rand_pattern(rng):
    # Build a pattern
    is_neg = rng.random() < 0.3
    use_slash = rng.random() < 0.5
    use_leading_slash = rng.random() < 0.2
    use_dir = rng.random() < 0.25
    n_segs = 1 if not use_slash else rng.randint(2, 3)
    segs = [rng.choice(GLOB_SEGS) for _ in range(n_segs)]
    pat = "/".join(segs)
    if use_leading_slash:
        pat = "/" + pat
    if use_dir:
        pat = pat + "/"
    if is_neg:
        pat = "!" + pat
